 v_hash constant text:='6d084c6bb98a488a88c2050b1a1465ed420fbf3b81f1ee79e7e3695ab403685d';
 v_url constant text:='https://www.datosabiertos.gob.pe/sites/default/files/01%20listado_entidades_2026_08.csv';
 v_cat constant text:='PE-SALY-DISCOVERY-2026-11-V0.2';
 v_evidence constant text:='SALY-PTE-L39-CAPTURE-001';
 v_parent text;
 v_checked timestamptz;
 v_receipt text;
 v_query_hash text;
 v_plan_hash text;
 v_run uuid; v_ejec uuid; v_query uuid;
 v_res jsonb; v_replay jsonb;
 v_count integer; v_lima integer; v_ica integer; v_missing integer;
BEGIN
 -- Must be bound to the real active Train run for this exact migration identity.
 SELECT execution_id INTO STRICT v_parent FROM public.lf_operation_execution
 WHERE operation_code='ACTUALIZACION_DB_LF' AND status='IN_PROGRESS'
 AND target_type='MIGRATION' AND target_repo='cristhianlujan/claude-persona-lf-patch'
 AND target_path ~ '^supabase/migrations/[0-9]{14}_lf_saly_ventas_pte_first_load_v1[.]sql$'
 AND manifest->>'producer'='lf-migration-merge-train';
 IF (SELECT count(*) FROM saly.proyecto WHERE codigo='SALY-001' AND estado='ACTIVO')<>1
 THEN RAISE EXCEPTION 'PTE_PROJECT_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM saly.ventas_discovery_ingestas WHERE source_id='PE-PTE') THEN
  RAISE EXCEPTION 'PTE_INITIAL_LOAD_ALREADY_EXISTS';
 END IF;
 IF encode(sha256(convert_to(v_capture,'UTF8')),'hex')<>v_hash
 OR jsonb_array_length(v_capture::jsonb)<>519 THEN RAISE EXCEPTION 'PTE_CAPTURE_DRIFT'; END IF;
 SELECT rights_checked_at INTO STRICT v_checked
 FROM saly.ventas_discovery_catalogo
 WHERE catalog_version=v_cat AND source_id='PE-PTE'
 AND connector_id='SALY-U07-S13-C03' AND substep_code='13.03'
 AND rights_status='LECTURA_AUTORIZADA' AND NOT persist_business_data AND NOT habilitada
 AND rights_evidence_ref='saly.evidencias:'||v_evidence FOR UPDATE;
 IF NOT EXISTS (SELECT 1 FROM saly.evidencias WHERE codigo=v_evidence
  AND hechos->>'license'='ODC-BY' AND hechos->>'resource_url'=v_url
  AND hechos->'filtered_capture'->>'capture_sha256'=v_hash
  AND (hechos->'filtered_capture'->>'rows')::integer=519)
 THEN RAISE EXCEPTION 'PTE_SOURCE_EVIDENCE_MISMATCH'; END IF;
 -- Owner-authorized first snapshot only. No operational EXECUTE grant.
 UPDATE saly.ventas_discovery_catalogo SET rights_status='PERSISTENCIA_PERMITIDA',
  persist_business_data=true,habilitada=true,runtime_status='PILOT_BOOTSTRAP_ONLY_NO_RUNTIME'
 WHERE catalog_version=v_cat AND source_id='PE-PTE';
 v_receipt:=v_url||'#captura-json-sha256='||v_hash;
 v_query_hash:=encode(sha256(convert_to('DSPTE01|2026-08|LIMA_ICA|15,11','UTF8')),'hex');
 v_plan_hash:=encode(sha256(convert_to('FIRST_LOAD_BOOTSTRAP_TRAIN|'||v_parent||'|'||v_hash,'UTF8')),'hex');
 INSERT INTO saly.ventas_discovery_runs(run_ref,catalog_version,scope,plan_hash,estado)
 VALUES(v_parent,v_cat,jsonb_build_object('mode','FIRST_LOAD_BOOTSTRAP_TRAIN','scope','LIMA_ICA',
 'commercial_runtime',false,'source_id','PE-PTE','capture_sha256',v_hash),v_plan_hash,'EN_EJECUCION') RETURNING id INTO v_run;
 INSERT INTO saly.ventas_discovery_plan_fuentes(run_id,catalog_version,source_id,connector_id,substep_code,scope_key,seleccion,estado)
 VALUES(v_run,v_cat,'PE-PTE','SALY-U07-S13-C03','13.03','LIMA_ICA','REQUIRED','PARCIAL');
 INSERT INTO saly.ventas_discovery_plan_batches(run_id,source_id,scope_key,batch_key,query_hash,filtros,estado)
 VALUES(v_run,'PE-PTE','LIMA_ICA','PTE-2026-08-B0001',v_query_hash,'{"ubigeo_prefix":["15","11"]}','FOUND');
 INSERT INTO saly.ventas_discovery_ejecuciones(run_id,catalog_version,source_id,connector_id,substep_code,scope_key,estado,evidencia_ref,ultima_consulta_en,total_encontrados)
 VALUES(v_run,v_cat,'PE-PTE','SALY-U07-S13-C03','13.03','LIMA_ICA','FOUND',v_receipt,v_checked,519) RETURNING id INTO v_ejec;
 INSERT INTO saly.ventas_discovery_consultas(ejecucion_id,run_id,run_ref,catalog_version,source_id,connector_id,substep_code,scope_key,batch_key,query_hash,herramienta,inicio,fin,estado,cantidad_hallazgos,evidencia_ref)
 VALUES(v_ejec,v_run,v_parent,v_cat,'PE-PTE','SALY-U07-S13-C03','13.03','LIMA_ICA','PTE-2026-08-B0001',v_query_hash,
 'CAPTURE_VERIFIED_REFERENCE',v_checked,v_checked,'FOUND',519,v_receipt) RETURNING id INTO v_query;
 v_res:=saly.ventas_pte_ingesta_core_v1(v_query,v_capture,'2026-08',v_url);
 IF v_res->>'status'<>'INSERTED' OR (v_res->>'filas')::int<>519 THEN RAISE EXCEPTION 'PTE_WRITE_FAILED'; END IF;
 v_replay:=saly.ventas_pte_ingesta_core_v1(v_query,v_capture,'2026-08',v_url);
 IF v_replay->>'status'<>'REPLAY' OR v_replay->>'ingesta_id' IS DISTINCT FROM v_res->>'ingesta_id'
 THEN RAISE EXCEPTION 'PTE_REPLAY_FAILED'; END IF;
 SELECT count(*),count(*) FILTER(WHERE ubigeo_candidato LIKE '15%'),count(*) FILTER(WHERE ubigeo_candidato LIKE '11%'),
 count(*) FILTER(WHERE estado_identidad='SIN_RUC')
 INTO v_count,v_lima,v_ica,v_missing FROM saly.ventas_hallazgos WHERE ingesta_id=(v_res->>'ingesta_id')::uuid;
 IF (v_count,v_lima,v_ica,v_missing) IS DISTINCT FROM (519,455,64,7)
 OR (SELECT count(*) FROM saly.ventas_discovery_ingestas WHERE consulta_id=v_query)<>1
 THEN RAISE EXCEPTION 'PTE_READBACK_MISMATCH'; END IF;
 UPDATE saly.ventas_discovery_runs SET estado='PARTIAL',finished_at=now() WHERE id=v_run;
 RAISE NOTICE 'PASS_PTE_FIRST_LOAD 519 rows, 455 Lima, 64 Ica, 7 missing RUC; parent %',v_parent;
END $pilot$;
COMMIT;
